macro_rules! deps {
    () => {
        ReplacerRef!();
        Captures!();
        Regex!();
    };
}

macro_rules! Replacer {
    () => {
        deps!();
        # [doc = " A trait for types that can be used to replace matches in a haystack."] # [doc = ""] # [doc = " In general, users of this crate shouldn't need to implement this trait,"] # [doc = " since implementations are already provided for `&str` along with other"] # [doc = " variants of string types, as well as `FnMut(&Captures) -> String` (or any"] # [doc = " `FnMut(&Captures) -> T` where `T: AsRef<str>`). Those cover most use cases,"] # [doc = " but callers can implement this trait directly if necessary."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows a basic implementation of  the `Replacer` trait. This"] # [doc = " can be done much more simply using the replacement string interpolation"] # [doc = " support (e.g., `$first $last`), but this approach avoids needing to parse"] # [doc = " the replacement string at all."] # [doc = ""] # [doc = " ```"] # [doc = " use regex::{Captures, Regex, Replacer};"] # [doc = ""] # [doc = " struct NameSwapper;"] # [doc = ""] # [doc = " impl Replacer for NameSwapper {"] # [doc = "     fn replace_append(&mut self, caps: &Captures<'_>, dst: &mut String) {"] # [doc = "         dst.push_str(&caps[\"first\"]);"] # [doc = "         dst.push_str(\" \");"] # [doc = "         dst.push_str(&caps[\"last\"]);"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " let re = Regex::new(r\"(?<last>[^,\\s]+),\\s+(?<first>\\S+)\").unwrap();"] # [doc = " let result = re.replace(\"Springsteen, Bruce\", NameSwapper);"] # [doc = " assert_eq!(result, \"Bruce Springsteen\");"] # [doc = " ```"] pub trait Replacer { # [doc = " Appends possibly empty data to `dst` to replace the current match."] # [doc = ""] # [doc = " The current match is represented by `caps`, which is guaranteed to"] # [doc = " have a match at capture group `0`."] # [doc = ""] # [doc = " For example, a no-op replacement would be `dst.push_str(&caps[0])`."] fn replace_append (& mut self , caps : & Captures < '_ > , dst : & mut String) ; # [doc = " Return a fixed unchanging replacement string."] # [doc = ""] # [doc = " When doing replacements, if access to [`Captures`] is not needed (e.g.,"] # [doc = " the replacement string does not need `$` expansion), then it can be"] # [doc = " beneficial to avoid finding sub-captures."] # [doc = ""] # [doc = " In general, this is called once for every call to a replacement routine"] # [doc = " such as [`Regex::replace_all`]."] fn no_expansion < 'r > (& 'r mut self) -> Option < Cow < 'r , str > > { None } # [doc = " Returns a type that implements `Replacer`, but that borrows and wraps"] # [doc = " this `Replacer`."] # [doc = ""] # [doc = " This is useful when you want to take a generic `Replacer` (which might"] # [doc = " not be cloneable) and use it without consuming it, so it can be used"] # [doc = " more than once."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex::{Regex, Replacer};"] # [doc = ""] # [doc = " fn replace_all_twice<R: Replacer>("] # [doc = "     re: Regex,"] # [doc = "     src: &str,"] # [doc = "     mut rep: R,"] # [doc = " ) -> String {"] # [doc = "     let dst = re.replace_all(src, rep.by_ref());"] # [doc = "     let dst = re.replace_all(&dst, rep.by_ref());"] # [doc = "     dst.into_owned()"] # [doc = " }"] # [doc = " ```"] fn by_ref < 'r > (& 'r mut self) -> ReplacerRef < 'r , Self > { ReplacerRef (self) } }
    };
}

Replacer!();